import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { once } from 'node:events';
import { resolve, join } from 'node:path';
import assert from 'node:assert/strict';
const directory = await mkdtemp(resolve('data', 'launch-check-'));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'launch.sqlite') },
  stdio: ['ignore', 'pipe', 'pipe'], detached: true,
});
let output = '';
child.stderr.on('data', chunk => { output += chunk; });
try {
  const port = await new Promise((resolvePort, reject) => {
    const timeout = setTimeout(() => reject(new Error(output || 'Startup timeout')), 5000);
    child.once('error', error => { clearTimeout(timeout); reject(error); });
    child.stdout.on('data', chunk => {
      const match = /listening on port (\\d+)/.exec(String(chunk));
      if (match) { clearTimeout(timeout); resolvePort(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start with PORT and DB_PATH: health check passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
EOF"

